// Obtenemos el texto plano que llega del nodo anterior.
const rawText = items[0].json.text;

// Array final donde guardaremos los resultados.
const finalResults = [];

// 1. EXTRAER INFORMACIÓN GLOBAL (TURNO Y HORARIOS)
const headerMatch = rawText.match(
  /(?<turno>FARMACIAS GDL \w+)\s*\(entrada\s*(?<entrada>\d{2}:\d{2})\s*y\s*salida\s*(?<salida>\d{2}:\d{2})\)/i
);
const globalInfo = headerMatch ? headerMatch.groups : {};

// 2. DIVIDIR EL TEXTO EN BLOQUES POR CADA RUTA
// El split ahora es más robusto para capturar el inicio de cada nueva ruta.
// Se usa una "mirada hacia adelante" para encontrar el patrón de "número_de_ruta\nRUTA número_de_ruta".
const routeBlocks = rawText.split(/(?=\n\d+\nRUTA \d+)/);

// 3. PROCESAR CADA BLOQUE DE RUTA INDIVIDUALMENTE
// `routeBlocks[0]` a veces contiene el encabezado global, por lo que lo omitimos si no tiene una ruta.
const processableBlocks = routeBlocks[0].includes('CRUCE') ? routeBlocks : routeBlocks.slice(1);

for (const block of processableBlocks) {
  const routeData = {
    turno: (globalInfo.turno || '').trim(),
    horario_entrada: (globalInfo.entrada || '').trim(),
    horario_salida: (globalInfo.salida || '').trim(),
    numero_ruta: '',
    nombre_ruta: '',
    descripcion_recorrido: '',
    paradas: []
  };

  // 4. EXTRAER EL NÚMERO Y NOMBRE DE LA RUTA
  // El regex modificado captura mejor los títulos de ruta complejos y la información que podría estar en varias líneas.
  const routeNameMatch = block.match(/\n\s*(\d+)\nRUTA\s*(\d+)\s*(.*)/i);
  if (routeNameMatch) {
    routeData.numero_ruta = routeNameMatch[2];
    routeData.nombre_ruta = `RUTA ${routeNameMatch[2]}${routeNameMatch[3] ? ` ${routeNameMatch[3].replace(/\n/g, ' ').replace(/\s+/g, ' ').trim()}` : ''}`;
  }

  // 5. EXTRAER LA DESCRIPCIÓN DEL RECORRIDO
  // Esta expresión regular es más precisa para encontrar el recorrido.
  // Busca el texto que va después de "SALE DE:" y se detiene justo antes del "CRUCE" o "DE SALIDA".
  const descriptionMatch = block.match(/SALE DE:\s*([\s\S]*?)(?=\nCRUCE|HORA|\n?INDEPENDECIA\sY\sPRIVADA|PROLONGACION GIGANTES|BLVRD NUEVO MÉXICO)/i);
  if (descriptionMatch) {
    routeData.descripcion_recorrido = descriptionMatch[1].replace(/\n/g, ' ').replace(/\s+/g, ' ').trim();
  } else {
    // Para el caso de la ruta 13 que no tiene el "CRUCE" o "DE SALIDA" después de la descripción.
    const fallbackDescriptionMatch = block.match(/SALE DE:\s*([\s\S]*?)(?=\nAV. MALECON Y HEBRON)/i);
    if (fallbackDescriptionMatch) {
      routeData.descripcion_recorrido = fallbackDescriptionMatch[1].replace(/\n/g, ' ').replace(/\s+/g, ' ').trim();
    }
  }

  // 6. EXTRAER LA LISTA DE PARADAS Y HORARIOS
  // Usamos una expresión regular global y multilínea para encontrar todas las paradas.
  // Ahora también maneja paradas que tienen texto adicional después de la hora.
  const stopsRegex = /^(.+)\s(\d{2}:\d{2})\s*$/gm;
  let match;
  while ((match = stopsRegex.exec(block)) !== null) {
    const cruce = match[1].trim();
    // Filtramos líneas no deseadas.
    if (cruce !== 'CRUCE' && cruce !== 'HORA' && !cruce.includes('SALE DE:') && !cruce.includes('(DE SALIDA')) {
      routeData.paradas.push({
        cruce: cruce,
        hora: match[2].trim()
      });
    }
  }

// 7. Manejar la ruta 7 que tiene un formato de paradas más irregular.
  // Se agrega una lógica específica para la última parada "CEDIS" que a veces no está en la línea correcta.
  if (routeData.numero_ruta === "7" && routeData.paradas.length > 0 && routeData.paradas[routeData.paradas.length - 1].cruce !== 'CEDIS') {
      const cedisMatch = block.match(/CEDIS\s+(\d{2}:\d{2})$/m);
      if (cedisMatch) {
          routeData.paradas.push({
              cruce: 'CEDIS',
              hora: cedisMatch[1].trim()
          });
      }
  }


  finalResults.push({ json: routeData });
}

// 8. Devolvemos el array de objetos estructurados a n8n.
return finalResults;
